const test=require('node:test'),assert=require('node:assert/strict'),dims=require('./woodland-dimensions.json');
const modulePromise=import('../working-woodland.js');
test('woodland presets preserve full-size assets, traffic clearance and charcoal separation',async()=>{const m=await modulePromise;for(const seed of [41,73])for(const preset of Object.keys(m.WOODLAND_PRESETS))for(const size of ['small','working']){const p=m.composeWoodland({seed,preset,size},dims),t=m.woodlandTerrain(p.recipe);assert.equal(p.items.filter(o=>o.model==='WW-001').length,size==='small'?3:6);assert.equal(p.routes.length,p.items.length+1);for(const o of p.items){assert(o.purpose);assert.equal(o.simulation,'planned');assert.equal(o.w,o.orientation?dims[o.model].d:dims[o.model].w);assert.equal(o.d,o.orientation?dims[o.model].w:dims[o.model].d);for(const q of p.items)if(q!==o)assert(Math.abs(q.x-o.x)>=(q.w+o.w)/2+1.49||Math.abs(q.z-o.z)>=(q.d+o.d)/2+1.49);for(const x of [-o.w/2,0,o.w/2])for(const z of [-o.d/2,0,o.d/2])assert(t.height(o.x+x,o.z+z)<=o.y+1e-8);}
for(const r of p.routes)for(let i=1;i<r.points.length;i++){const a=r.points[i-1],b=r.points[i];for(let f=0;f<=1;f+=.2){const x=a.x+(b.x-a.x)*f,z=a.z+(b.z-a.z)*f;for(const o of p.items){if(r.to===o.id&&i===r.points.length-1)continue;assert(!(Math.abs(x-o.x)<o.w/2+r.width/2-.02&&Math.abs(z-o.z)<o.d/2+r.width/2-.02),`${preset}: ${r.id} intersects ${o.id}`);}}}
for(const reserve of p.reservations){for(const o of p.items.filter(o=>o.id!=='processing'))assert(Math.hypot(o.x-reserve.x,o.z-reserve.z)>=reserve.radius+Math.hypot(o.w,o.d)/2);for(const o of p.forest)assert(Math.hypot(o.x-reserve.x,o.z-reserve.z)>=reserve.radius+Math.hypot(dims['tree-standing'].w,dims['tree-standing'].d)/2);}
assert(p.forest.length>150,'The woodland must remain substantially forested');for(const r of p.routes.slice(1))assert(p.routes.some(parent=>parent.id===r.from&&parent.points.some(j=>Math.hypot(j.x-r.points[0].x,j.z-r.points[0].z)<.01)),'Every branch joins a real parent route');assert.equal(p.interfaces[0].status,'candidate');assert.equal(p.semantics.undecided.yield,null);}});
test('woodland recipe reconstructs deterministically and clipping does not rearrange its work',async()=>{const m=await modulePromise,a=m.composeWoodland({},dims),b=m.composeWoodland({carved:false},dims);assert.deepEqual(a,m.composeWoodland(a.recipe,dims));assert.deepEqual(a.items,b.items);assert.deepEqual(a.routes,b.routes);assert.deepEqual(a.forest,b.forest);assert.throws(()=>m.composeWoodland({preset:'invalid'},dims));assert.throws(()=>m.composeWoodland({}, {...dims,'WW-004':{w:100,d:100,h:3}}),/cannot support/);});
